pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // actor claims the initial airdrop, shifting totalDistributed vs totalRemaining
        vm.prank(actor);
        c.getTokens();
        // actor takes ownership via NETM()
        vm.prank(actor);
        c.NETM();
        // General rule: after NETM(), the (new) owner's balance equals totalDistributed,
        // since NETM credits the distributed amount, not the remaining amount.
        assertTrue(c.balanceOf(actor) == c.totalDistributed());
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor.code.length == 0);
        address owner = c.owner();
        vm.assume(actor != owner);

        // a non-blacklisted actor claims the airdrop, changing totalDistributed/totalRemaining
        vm.prank(actor);
        c.getTokens();

        // owner re-initializes ownership/balance via NETM
        vm.prank(owner);
        c.NETM();

        assertTrue(c.balanceOf(c.owner()) == c.totalDistributed());
    }
}
